    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    # Flood-fill 4-connected non-background cells; each colored marker selects
    # its entire connected shape. Recolor the centers of all solid 3x3 windows
    # in that shape with the marker's color.
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if original[r][c] == 0 or (r, c) in seen:
