            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            colors = set()
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if original[y][x] not in (0, 1):
                    colors.add(original[y][x])
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
